style.css:
@-moz-document domain("google.com") {
body {
        background: url(https://i.postimg.cc/CKwY8Q78/image.jpg) no-repeat center center fixed !important;
        background-size: cover !important;
        color: #D1B8F9 !important; /* Lila medio para el texto */
    }

    html, body {
        background-color: transparent !important; /* Mantener el fondo limpio */
        color: #D1B8F9 !important; /* Lila para el texto */
    }

    /* Enlaces con color lila más oscuro */
    a {
        color: #B1A0E6 !important; /* Lila más oscuro para los enlaces */
        text-decoration: none !important;
    }

    /* Botones semi-translúcidos */
    button {
        background-color: rgba(106, 78, 159, 0.6) !important; /* Lila apagado semi-transparente */
        color: #E1D1F9 !important; /* Lila más claro para el texto */
        border: 2px solid #6A4E9F !important; /* Borde lila apagado */
        padding: 10px 15px !important;
        border-radius: 5px !important;
        transition: background-color 0.3s ease !important; /* Efecto suave al pasar el ratón */
    }

    button:hover {
        background-color: rgba(106, 78, 159, 0.8) !important; /* Un poco más opaco al pasar el ratón */
    }

    /* Formularios (input y textarea) con fondo transparente */
    input, textarea {
        background-color: transparent !important; /* Fondo transparente */
        color: #E1D1F9 !important; /* Lila más claro para el texto */
        border: 1px solid #6A4E9F !important; /* Borde lila apagado */
    }

    /* Elementos de navegación y pie de página con fondo lila apagado */
    nav, footer {
        background-color: #6A4E9F !important; /* Lila apagado */
        color: #E1D1F9 !important; /* Lila más claro para el texto */
    }

    /* Asegurar que los demás elementos NO tengan bordes innecesarios */
    div, p, span, h1, h2, h3, h4, h5, h6, ul, li {
        border: none !important; /* Eliminar bordes innecesarios */
        background-color: transparent !important; /* Mantener fondos transparentes */
    }
}
